import struct
def read_gguf_meta(path, keys):
    out={}
    with open(path,'rb') as f:
        magic=f.read(4)
        if magic!=b'GGUF': print(path,'não é GGUF'); return out
        ver=struct.unpack('<I',f.read(4))[0]
        n_tensors=struct.unpack('<Q',f.read(8))[0]
        n_kv=struct.unpack('<Q',f.read(8))[0]
        for _ in range(n_kv):
            klen=struct.unpack('<Q',f.read(8))[0]; k=f.read(klen).decode()
            t=struct.unpack('<I',f.read(4))[0]
            if t==0: f.read(1)  # bool
            elif t==1: f.read(4)
            elif t==2: f.read(4)
            elif t==3: f.read(8)
            elif t==4: f.read(4)  # float32
            elif t==5: f.read(8)
            elif t==6: sl=struct.unpack('<Q',f.read(8))[0]; f.read(sl)
